"491 :   private List<String> processArgs(String[] args) {
492 :     // Args4j has a different format that the old command-line parser.
493 :     // So we use some voodoo to get the args into the format that args4j
494 :     // expects.
495 :     Pattern argPattern = Pattern.compile("(--[a-zA-Z_]+)=(.*)");
496 :     Pattern quotesPattern = Pattern.compile("^['\"](.*)['\"]$");
497 :     List<String> processedArgs = Lists.newArrayList();
498 : 
499 :     for (String arg : args) {
500 :       Matcher matcher = argPattern.matcher(arg);
501 :       if (matcher.matches()) {
502 :         processedArgs.add(matcher.group(1));
503 : 
504 :         String value = matcher.group(2);
505 :         Matcher quotesMatcher = quotesPattern.matcher(value);
506 :         if (quotesMatcher.matches()) {
507 :           processedArgs.add(quotesMatcher.group(1));
508 :         } else {
509 :           processedArgs.add(value);
510 :         }
511 :       } else {
512 :         processedArgs.add(arg);
513 :       }
514 :     }
515 : 
516 :     return processedArgs;
517 :   }"

